// Orthodontic Centres signature add-in: puts the right signature into every new email, reply and
// forward, and swaps it when the From address changes (e.g. to maidenhead@), like CodeTwo's add-in.
// OCSIG (the pre-rendered signatures and their pictures) is prepended to this file by build.py.
// Plain ES5 with callbacks: classic Outlook on Windows runs this in its own small JavaScript runtime.

// FNV-1a hash of the lower-case address; build.py keys staff signatures by it so the public file
// doesn't list everyone's email address.
function ocsigHash(s) {
  var h = 0x811c9dc5;
  for (var i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}

// The signature for a sender address: {html, images: [file names]}, or null for anyone we don't sign.
function ocsigFor(address) {
  var a = (address || '').toLowerCase();
  if (OCSIG.clinics[a]) return OCSIG.clinics[a];
  var p = OCSIG.people[ocsigHash(a)];
  if (!p) return null;
  return { html: p.html.split('{{EMAIL}}').join(a), images: p.images };
}

// Pictures go in as inline attachments named "ocsig-..."; the ones from a previous signature are
// removed first so changing From doesn't leave stray attachments behind.
function ocsigRemoveOld(item, done) {
  if (!item.getAttachmentsAsync) { done(); return; }
  item.getAttachmentsAsync(function (r) {
    var old = [];
    if (r.status === Office.AsyncResultStatus.Succeeded) {
      for (var i = 0; i < r.value.length; i++) if (/^ocsig-/.test(r.value[i].name)) old.push(r.value[i].id);
    }
    (function next() {
      if (!old.length) { done(); return; }
      item.removeAttachmentAsync(old.shift(), function () { next(); });
    })();
  });
}

function ocsigAddImages(item, names, done) {
  var list = names.slice(), failed = [];
  (function next() {
    if (!list.length) { done(failed); return; }
    var n = list.shift();
    item.addFileAttachmentFromBase64Async(OCSIG.images[n], 'ocsig-' + n, { isInline: true }, function (r) {
      if (r.status !== Office.AsyncResultStatus.Succeeded) failed.push(n + ': ' + (r.error && r.error.message));
      next();
    });
  })();
}

// TEMPORARY diagnostic (15 Nov 2026): shows how far the add-in got as a bar at the top of the new
// email, because the add-in's own console can't be read in Outlook on the web. Set false to turn off.
var OCSIG_DIAG = true;
function ocsigDiag(item, text) {
  if (OCSIG_DIAG && typeof console !== 'undefined') console.log('[ocsig] ' + text);
  if (!OCSIG_DIAG || !item || !item.notificationMessages) return;
  try {
    item.notificationMessages.replaceAsync('ocsigdiag', {
      type: Office.MailboxEnums.ItemNotificationMessageType.ErrorMessage,
      message: ('Signature add-in: ' + text).slice(0, 150)
    });
  } catch (e) {}
}
function ocsigErr(r) { return r.status === Office.AsyncResultStatus.Succeeded ? 'ok' : 'FAILED ' + (r.error && (r.error.code + ' ' + r.error.message)); }

function ocsigApply(event) {
  if (OCSIG_DIAG && typeof console !== 'undefined') console.log('[ocsig] handler called');
  var item = Office.context.mailbox.item;
  var finish = function () { event.completed(); };
  try {
    ocsigDiag(item, '1 started (' + Office.context.diagnostics.platform + ' ' + Office.context.diagnostics.version + ')');
    item.from.getAsync(function (r) {
      try {
        var from = (r.status === Office.AsyncResultStatus.Succeeded && r.value && r.value.emailAddress) ||
                   Office.context.mailbox.userProfile.emailAddress;
        var sig = ocsigFor(from);
        ocsigDiag(item, '2 from ' + from + ' (getAsync ' + ocsigErr(r) + '), signature ' + (sig ? 'found' : 'NOT found'));
        if (!sig) { finish(); return; }   // not someone we sign for: leave Outlook's own signature alone
        var set = function (dr) {
          ocsigRemoveOld(item, function () {
            ocsigAddImages(item, sig.images, function (failed) {
              item.body.setSignatureAsync(sig.html, { coercionType: Office.CoercionType.Html }, function (sr) {
                ocsigDiag(item, '3 done for ' + from + ' (' + (event.type || '?') + '): disable ' + (dr ? ocsigErr(dr) : 'n/a') + ', images ' +
                  (sig.images.length - failed.length) + '/' + sig.images.length + (failed.length ? ' ' + failed[0] : '') +
                  ', setSignature ' + ocsigErr(sr));
                finish();
              });
            });
          });
        };
        // stop Outlook adding its own signature (from the Intune script) on top of ours
        if (item.disableClientSignatureAsync) item.disableClientSignatureAsync(set); else set();
      } catch (e) { ocsigDiag(item, 'ERROR ' + e.message); finish(); }
    });
  } catch (e) { ocsigDiag(item, 'ERROR ' + e.message); finish(); }
}

function onNewMessageComposeHandler(event) { ocsigApply(event); }
function onMessageFromChangedHandler(event) { ocsigApply(event); }

if (OCSIG_DIAG && typeof console !== 'undefined') console.log('[ocsig] script loaded, registering handlers');
Office.actions.associate('onNewMessageComposeHandler', onNewMessageComposeHandler);
Office.actions.associate('onMessageFromChangedHandler', onMessageFromChangedHandler);
